    id: "50257",
    title: "Late Rtr. Santosh Memorial Nationwide Rota Quiz 2024-25, Zonal Round",
    slug: "late-rtr-santosh-memorial-nationwide-rota-quiz-2024-25-zonal-50257",
    avenue: "Club Administration",
    projectType: "Hosted",
    tenure: "2024-25",
